			.chat-msg-edit-cancel { background: transparent; color: rgba(255,255,255,0.85); }
			.chat-msg-edit-cancel:hover { background: rgba(255,255,255,0.12); }
			@media (max-width: 600px) {
				.chat-msg-edit-inline { opacity: 1; }
