			.chat-reload-btn {
				background: #10a37f;
				color: #fff;
				border: none;
				border-radius: 8px;
				padding: 10px 20px;
				font-size: 14px;
				font-weight: 600;
				cursor: pointer;
				transition: background 0.15s, transform 0.1s;
