			function readProjects() {
				if (!projectsSeeded) {
					projectsSeeded = true;
					try {
						var raw = window.localStorage.getItem(PROJECTS_KEY);
						var list = raw ? JSON.parse(raw) : [];
						projectsCache = Array.isArray(list) ? list : [];
