					elProjectFileAddBtn.disabled = files.length >= PROJECT_FILES_MAX_COUNT || !cloudProjectsLoggedIn;
elProjectFileAddBtn.title = files.length >= PROJECT_FILES_MAX_COUNT ? t('files_limit') : t('new_file');
				}
