					if (elProfileMenu.hidden) openProfileMenu(); else closeProfileMenu();
				});
			}
			document.addEventListener('click', function(e) {
				if (elProfileMenu && !elProfileMenu.hidden && !elProfileMenu.contains(e.target) && e.target !== elProfileTrigger) {
					closeProfileMenu();
