function commentNameHint(source) {
var lines = String(source || '').split(/\r?\n/).slice(0, 20);
for (var i = 0; i < lines.length; i++) {
  var line = lines[i].trim()
    .replace(/^(?:\/{2,3}|\/\*+|#|--|;+|<!--|\*+)\s*/, '')
    .replace(/\s*(?:\*\/|-->|-->)\s*$/, '')
