			var v = parseInt(localStorage.getItem(NEWS_LAST_SEEN_KEY), 10);
			return isNaN(v) ? 0 : v;
		}
		function setNewsLastSeenId(id) {
			try { localStorage.setItem(NEWS_LAST_SEEN_KEY, String(id)); } catch (e) {}
