		}
		function markNewsRead(items) {
			var maxId = getNewsLastSeenId();
			(items || []).forEach(function(item) { if (item.id > maxId) maxId = item.id; });
			setNewsLastSeenId(maxId);
			updateNewsBadge(items);
		}
