					body: JSON.stringify({ title: title, body: body })
				}).then(function() {
					elNewsTitleInput.value = '';
					elNewsBodyInput.value = '';
					loadNews(true);
				}).finally(function() { elNewsPublishBtn.disabled = false; });
			});
		}

